def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def sumSubtreeRanges(tree):
    val, left, right = parse(tree)
    n = len(val)
    mx = val[:]
    mn = val[:]
    total = 0
    for u in range(n - 1, -1, -1):
        for c in (left[u], right[u]):
            if c != -1:
                mx[u] = max(mx[u], mx[c])
                mn[u] = min(mn[u], mn[c])
        total += mx[u] - mn[u]
    return total
